  $hb2json${"slug": "human-behavior-in-the-social-environment-ii", "title": "Human Behavior in the Social Environment II", "description": "Extend HBSE I from individual life-course development into families, groups, organizations, communities, institutions, and global systems. Students use systems and ecological concepts to analyze family and group dynamics, human service organizations, communities, social structures, power and oppression, culture and migration, economic inequality, collective trauma, globalization, macro assessment, advocacy, and multi-level change.", "topics": [{"id": "aaddd495-c5cc-4dc9-b922-4bf1b13cc604", "type": "topic", "title": "HBSE II as Mezzo-Macro Person-in-Environment Practice", "description": "Extend HBSE I from individual life-course development into families, groups, organizations, communities, institutions, and global systems.", "children": [{"id": "0d8c67ff-8706-4081-8639-e6acacdec2ec", "type": "subtopic", "title": "From individual development to social environments", "children": [{"id": "8177160d-a285-4c04-97d4-e765a808505f", "type": "concept", "title": "Continuity with HBSE I"}, {"id": "24c87b33-21ee-4619-8cb2-309dd2e95b46", "type": "concept", "title": "Micro-mezzo-macro integration"}, {"id": "c5efc11d-2422-4d2b-9f8f-b56c5c58c9e9", "type": "concept", "title": "Environment as active context"}, {"id": "388abdad-34cd-42d1-8573-d8ec7e43165e", "type": "concept", "title": "Practice implications"}], "description": "HBSE II shows how human behavior is shaped by relationships, institutions, communities, and macro systems."}, {"id": "d267ca6a-8bea-4ec6-98b6-3c92219baaf1", "type": "subtopic", "title": "Mezzo and macro levels of analysis", "children": [{"id": "7e932fd5-a2e9-441e-a35b-c692bddef160", "type": "concept", "title": "Families"}, {"id": "4a8f387d-fe7a-4f32-b5da-a88d44d39576", "type": "concept", "title": "Groups"}, {"id": "c0b0d91c-ded9-4fdc-82d6-fb4c3e03f01d", "type": "concept", "title": "Organizations"}, {"id": "546cf92d-37b7-4555-a616-5abc723ccb9b", "type": "concept", "title": "Communities and policy systems"}], "description": "Students learn to shift scale without losing sight of lived experience."}, {"id": "84d4a9d5-7267-4323-8924-cf9c759bc748", "type": "subtopic", "title": "Social work values in systems analysis", "children": [{"id": "ff7dbb09-13a8-4398-8f15-f1c0043ec61b", "type": "concept", "title": "NASW values"}, {"id": "406b372e-b521-42b0-a879-d4703ffada16", "type": "concept", "title": "CSWE competency alignment"}, {"id": "0548cdc3-0e34-4846-940f-badf79cdbe29", "type": "concept", "title": "Client and community self-determination"}, {"id": "38ea419d-2685-4797-9187-9128b8464e8b", "type": "concept", "title": "Ethical use of authority"}], "description": "Systems analysis must stay connected to dignity, justice, relationship, service, and competence."}]}, {"id": "46d0d2c0-03d3-45a6-b758-b8325494cfe2", "type": "topic", "title": "Systems Theory, Ecological Thinking, and Social Complexity", "description": "Use systems and ecological concepts to understand reciprocal influence, feedback, adaptation, and change across social environments.", "children": [{"id": "fac866c0-5b10-4950-8eda-5e98568aa7d0", "type": "subtopic", "title": "Core systems concepts", "children": [{"id": "1a65493c-85c9-402c-9187-d67d2bb1dd01", "type": "concept", "title": "Boundaries"}, {"id": "399dba3b-a31d-4f0f-856b-4a9e5c6069eb", "type": "concept", "title": "Inputs and outputs"}, {"id": "455320d9-a4b5-426c-917d-ce6be1d05ec2", "type": "concept", "title": "Feedback loops"}, {"id": "fb544ad4-ffe1-4932-a30e-98c5bc936a68", "type": "concept", "title": "Homeostasis and adaptation"}], "description": "Systems concepts give students a vocabulary for relationships, patterns, feedback, and change."}, {"id": "b4b6e13a-22c9-40f5-849c-fb1732177a8d", "type": "subtopic", "title": "Ecological perspective", "children": [{"id": "915da456-3081-4855-a413-85317cdb8c2b", "type": "concept", "title": "Microsystem"}, {"id": "f7ba28d0-4d8c-41d5-ab24-6df6cd243c51", "type": "concept", "title": "Mesosystem"}, {"id": "ac31a1ec-8e2f-44be-b7c1-a585c666ab37", "type": "concept", "title": "Exosystem"}, {"id": "9474d2b0-1112-47a2-ab00-f3ba94f1d2d9", "type": "concept", "title": "Macrosystem and chronosystem"}], "description": "Ecological thinking helps students understand people inside nested environments and historical time."}, {"id": "80301314-d5a8-4576-a103-cd2795eb6b79", "type": "subtopic", "title": "Complexity and unintended consequences", "children": [{"id": "a6dbb09b-081a-4b29-b864-4884b84f8f60", "type": "concept", "title": "Nonlinear change"}, {"id": "e2aa524f-c1a9-4ea1-b657-1c19d5d90b12", "type": "concept", "title": "Emergence"}, {"id": "49b0141f-0fb7-4799-8395-d529ca83b6a9", "type": "concept", "title": "System leverage points"}, {"id": "adb02006-3f30-46b1-8127-09dadec2f980", "type": "concept", "title": "Adaptive problems"}], "description": "Social interventions often produce ripple effects, so students learn to anticipate dynamic consequences."}]}, {"id": "e5a4e1e6-dcd0-4339-9728-46c74a35798f", "type": "topic", "title": "Families and Family Systems Across Cultures", "description": "Analyze families as relational, cultural, developmental, economic, and political systems rather than fixed household forms.", "children": [{"id": "92619efd-3383-41e1-a048-0cb7f0cea161", "type": "subtopic", "title": "Family systems theory", "children": [{"id": "1bcde1e8-3e1d-409a-8fc8-33bfca3d2457", "type": "concept", "title": "Subsystems"}, {"id": "5844eb90-41c4-49d8-94b2-057ada5defe4", "type": "concept", "title": "Boundaries"}, {"id": "046ce121-49d3-4576-92e9-d160db0e5292", "type": "concept", "title": "Triangles"}, {"id": "d7277744-33e2-476d-893f-06e18c656f61", "type": "concept", "title": "Family life cycle"}], "description": "Family systems theory explains behavior through roles, rules, patterns, boundaries, and relational meanings."}, {"id": "e8c1ef59-b7b0-4f73-b2a4-8dbd2018096a", "type": "subtopic", "title": "Diversity in family forms", "children": [{"id": "32cd43a9-5ca0-4d71-933b-894891127c85", "type": "concept", "title": "Single-parent families"}, {"id": "7042b3c1-f7c2-468b-ba09-e2a425104213", "type": "concept", "title": "Blended families"}, {"id": "da8d5907-97ac-4b26-babf-c2426d9e7fa4", "type": "concept", "title": "Chosen families"}, {"id": "f9eb480c-9f00-4cc4-a1c1-44c343d42a40", "type": "concept", "title": "Multigenerational and kinship networks"}], "description": "Students examine families without treating one structure as the universal norm."}, {"id": "983d152c-c6e6-4353-ab4c-00f5f32680a8", "type": "subtopic", "title": "Family stress and support", "children": [{"id": "2cbdba3c-144f-4f71-8aca-386584ececda", "type": "concept", "title": "Caregiving strain"}, {"id": "e85be27f-537c-4868-b092-c658f1d27dfd", "type": "concept", "title": "Economic stress"}, {"id": "93635a37-96f7-4fe9-b91c-4b174601dd3b", "type": "concept", "title": "Social support"}, {"id": "90e60430-c4e5-4312-b78d-2321ad3f35bc", "type": "concept", "title": "Resilience and family strengths"}], "description": "Family functioning depends on resources, cultural meaning, stress, and access to support."}]}, {"id": "486b8cee-b9ea-42b6-b553-cf910dd9c786", "type": "topic", "title": "Group Dynamics, Mutual Aid, and Collective Change", "description": "Understand how groups shape identity, support, power, conflict, decision-making, and social work intervention.", "children": [{"id": "6cee39e5-9578-4de8-b82a-acd17c251500", "type": "subtopic", "title": "Group development and process", "children": [{"id": "c829826f-5869-4c93-b8fd-1b57b9d7985d", "type": "concept", "title": "Forming, storming, norming, performing"}, {"id": "22da00a5-7117-418e-ad87-c43cb65535f2", "type": "concept", "title": "Roles and norms"}, {"id": "03422fef-4aaf-4b05-8f93-1e3ef4faae47", "type": "concept", "title": "Cohesion"}, {"id": "8d0768ba-7c25-4d33-b969-a13e85dfd06c", "type": "concept", "title": "Conflict and repair"}], "description": "Groups have developmental patterns that affect trust, participation, conflict, and productivity."}, {"id": "0a2ed224-53d7-4406-8521-5607ef2f2bfa", "type": "subtopic", "title": "Mutual aid and therapeutic group principles", "children": [{"id": "fd94ae5e-be64-498e-8377-d099e08c181e", "type": "concept", "title": "Universality"}, {"id": "fbc7b700-acf6-453a-ab86-9000b89941e7", "type": "concept", "title": "Mutual support"}, {"id": "a31b8a62-67b9-49fa-9ff7-b123014dc6ca", "type": "concept", "title": "Peer learning"}, {"id": "a832202e-43fe-4483-932a-80d518ecadb0", "type": "concept", "title": "Facilitation stance"}], "description": "Groups can create change through shared experience, reciprocity, skill practice, and belonging."}, {"id": "b3560598-22e3-48f8-95f4-46934e6a7f21", "type": "subtopic", "title": "Task groups and collective action", "children": [{"id": "03cf2c4b-d709-4910-a192-a0158ad98888", "type": "concept", "title": "Committees and teams"}, {"id": "6f5231f3-ab99-4e06-8ce5-209f6cbcfe02", "type": "concept", "title": "Coalitions"}, {"id": "b8c19a7e-a73a-4368-b3a2-c02ac936173c", "type": "concept", "title": "Leadership distribution"}, {"id": "e7213c35-4a52-49e1-b1ad-796192907dc6", "type": "concept", "title": "Decision rules and accountability"}], "description": "Groups are also engines for planning, advocacy, governance, and community change."}]}, {"id": "f064b20e-c1bd-414a-bb31-0f110ff4d8aa", "type": "topic", "title": "Organizations as Human Service Environments", "description": "Study how organizations structure behavior, ethics, worker experience, service access, and client outcomes.", "children": [{"id": "f689da7d-2d03-40e9-b532-67109264a542", "type": "subtopic", "title": "Organizational behavior and culture", "children": [{"id": "f7a5a211-5801-4728-b3ab-f14acae14dae", "type": "concept", "title": "Formal and informal culture"}, {"id": "c9177df8-bf16-43e3-929d-e92da16c6ca2", "type": "concept", "title": "Mission and values"}, {"id": "aad0c513-e98d-4f41-9234-5e643d730199", "type": "concept", "title": "Incentives and constraints"}, {"id": "4872ff3d-7c43-4a10-843a-07e597039c45", "type": "concept", "title": "Street-level bureaucracy"}], "description": "Organizations shape what workers do, what clients receive, and what ethical choices feel possible."}, {"id": "e49e70b2-f997-419e-8427-90578675afb0", "type": "subtopic", "title": "Human service organizations", "children": [{"id": "99a561f9-4912-4910-8d5a-17bc09da6720", "type": "concept", "title": "Intake and referral"}, {"id": "01488191-e8d6-4297-9fab-818546997b9d", "type": "concept", "title": "Caseloads and workflow"}, {"id": "0175539f-da22-463a-bbe7-d3fcf5bff297", "type": "concept", "title": "Supervision and documentation"}, {"id": "4a706528-239d-4860-94e8-a87dcdfa4f94", "type": "concept", "title": "Interagency coordination"}], "description": "Students learn how social service organizations organize access, eligibility, service quality, and risk."}, {"id": "5088825e-eca9-4e19-9cbd-c5376c65a6f4", "type": "subtopic", "title": "Organizational trauma and worker sustainability", "children": [{"id": "d7d4aaef-63e0-4355-b03b-3ce98c334409", "type": "concept", "title": "Burnout and moral distress"}, {"id": "6a3db923-746c-499d-a7e7-567428b981e6", "type": "concept", "title": "Secondary traumatic stress"}, {"id": "1fd9ab43-d580-4014-8721-9d8761ae5cab", "type": "concept", "title": "Psychological safety"}, {"id": "81e40c37-addf-4540-ad0e-5ba70a46cccb", "type": "concept", "title": "Reflective supervision"}], "description": "Organizational environments can support or harm workers and clients."}]}, {"id": "2dda78ac-2415-49b2-9da4-8badaeca53b4", "type": "topic", "title": "Communities as Social Systems", "description": "Analyze neighborhoods, networks, social capital, institutions, place, and community power as environments that shape well-being.", "children": [{"id": "c37ace22-fdc0-4c29-95a2-add37cdbe5c4", "type": "subtopic", "title": "Community concepts and boundaries", "children": [{"id": "57c64210-eb64-48c4-9435-eadcbc241ad2", "type": 