set
  title = 'Human Behavior in the Social Environment II',
  goal = 'Human Behavior in the Social Environment II',
  summary = 'Extend HBSE I from individual life-course development into families, groups, organizations, communities, institutions, and global systems. Students use systems and ecological concepts to analyze family and group dynamics, human service organizations, communities, social structures, power and oppression, culture and migration, economic inequality, collective trauma, globalization, macro assessment, advocacy, and multi-level change.',
  data = $hb2json${"slug": "human-behavior-in-the-social-environment-ii", "title": "Human Behavior in the Social Environment II", "description": "Extend HBSE I from individual life-course development into families, groups, organizations, communities, institutions, and global systems. Students use systems and ecological concepts to analyze family and group dynamics, human service organizations, communities, social structures, power and oppression, culture and migration, economic inequality, collective trauma, globalization, macro assessment, advocacy, and multi-level change.", "topics": [{"id": "aaddd495-c5cc-4dc9-b922-4bf1b13cc604", "type": "topic", "title": "HBSE II as Mezzo-Macro Person-in-Environment Practice", "description": "Extend HBSE I from individual life-course development into families, groups, organizations, communities, institutions, and global systems.", "children": [{"id": "0d8c67ff-8706-4081-8639-e6acacdec2ec", "type": "subtopic", "title": "From individual development to social environments", "children": [{"id": "8177160d-a285-4c04-97d4-e765a808505f", "type": "concept", "title": "Continuity with HBSE I"}, {"id": "24c87b33-21ee-4619-8cb2-309dd2e95b46", "type": "concept", "title": "Micro-mezzo-macro integration"}, {"id": "c5efc11d-2422-4d2b-9f8f-b56c5c58c9e9", "type": "concept", "title": "Environment as active context"}, {"id": "388abdad-34cd-42d1-8573-d8ec7e43165e", "type": "concept", "title": "Practice implications"}], "description": "HBSE II shows how human behavior is shaped by relationships, institutions, communities, and macro systems."}, {"id": "d267ca6a-8bea-4ec6-98b6-3c92219baaf1", "type": "subtopic", "title": "Mezzo and macro levels of analysis", "children": [{"id": "7e932fd5-a2e9-441e-a35b-c692bddef160", "type": "concept", "title": "Families"}, {"id": "4a8f387d-fe7a-4f32-b5da-a88d44d39576", "type": "concept", "title": "Groups"}, {"id": "c0b0d91c-ded9-4fdc-82d6-fb4c3e03f01d", "type": "concept", "title": "Organizations"}, {"id": "546cf92d-37b7-4555-a616-5abc723ccb9b", "type": "concept", "title": "Communities and policy systems"}], "description": "Students learn to shift scale without losing sight of lived experience."}, {"id": "84d4a9d5-7267-4323-8924-cf9c759bc748", "type": "subtopic", "title": "Social work values in systems analysis", "children": [{"id": "ff7dbb09-13a8-4398-8f15-f1c0043ec61b", "type": "concept", "title": "NASW values"}, {"id": "406b372e-b521-42b0-a879-d4703ffada16", "type": "concept", "title": "CSWE competency alignment"}, {"id": "0548cdc3-0e34-4846-940f-badf79cdbe29", "type": "concept", "title": "Client and community self-determination"}, {"id": "38ea419d-2685-4797-9187-9128b8464e8b", "type": "concept", "title": "Ethical use of authority"}], "description": "Systems analysis must stay connected to dignity, justice, relationship, service, and competence."}]}, {"id": "46d0d2c0-03d3-45a6-b758-b8325494cfe2", "type": "topic", "title": "Systems Theory, Ecological Thinking, and Social Complexity", "description": "Use systems and ecological concepts to understand reciprocal influence, feedback, adaptation, and change across social environments.", "children": [{"id": "fac866c0-5b10-4950-8eda-5e98568aa7d0", "type": "subtopic", "title": "Core systems concepts", "children": [{"id": "1a65493c-85c9-402c-9187-d67d2bb1dd01", "type": "concept", "title": "Boundaries"}, {"id": "399dba3b-a31d-4f0f-856b-4a9e5c6069eb", "type": "concept", "title": "Inputs and outputs"}, {"id": "455320d9-a4b5-426c-917d-ce6be1d05ec2", "type": "concept", "title": "Feedback loops"}, {"id": "fb544ad4-ffe1-4932-a30e-98c5bc936a68", "type": "concept", "title": "Homeostasis and adaptation"}], "description": "Systems concepts give students a vocabulary for relationships, patterns, feedback, and change."}, {"id": "b4b6e13a-22c9-40f5-849c-fb1732177a8d", "type": "subtopic", "title": "Ecological perspective", "children": [{"id": "915da456-3081-4855-a413-85317cdb8c2b", "type": "concept", "title": "Microsystem"}, {"id": "f7ba28d0-4d8c-41d5-ab24-6df6cd243c51", "type": "concept", "title": "Mesosystem"}, {"id": "ac31a1ec-8e2f-44be-b7c1-a585c666ab37", "type": "concept", "title": "Exosystem"}, {"id": "9474d2b0-1112-47a2-ab00-f3ba94f1d2d9", "type": "concept", "title": "Macrosystem and chronosystem"}], "description": "Ecological thinking helps students understand people inside nested environments and historical time."}, {"id": "80301314-d5a8-4576-a103-cd2795eb6b79", "type": "subtopic", "title": "Complexity and unintended consequences", "children": [{"id": "a6dbb09b-081a-4b29-b864-4884b84f8f60", "type": "concept", "title": "Nonlinear change"}, {"id": "e2aa524f-c1a9-4ea1-b657-1c19d5d90b12", "type": "concept", "title": "Emergence"}, {"id": "49b0141f-0fb7-4799-8395-d529ca83b6a9", "type": "concept", "title": "System leverage points"}, {"id": "adb02006-3f30-46b1-8127-09dadec2f980", "type": "concept", "title": "Adaptive problems"}], "description": "Social interventions often produce ripple effects, so students learn to anticipate dynamic consequences."}]}, {"id": "e5a4e1e6-dcd0-4339-9728-46c74a35798f", "type": "topic", "title": "Families and Family Systems Across Cultures", "description": "Analyze families as relational, cultural, developmental, economic, and political systems rather than fixed household forms.", "children": [{"id": "92619efd-3383-41e1-a048-0cb7f0cea161", "type": "subtopic", "title": "Family systems theory", "children": [{"id": "1bcde1e8-3e1d-409a-8fc8-33bfca3d2457", "type": "concept", "title": "Subsystems"}, {"id": "5844eb90-41c4-49d8-94b2-057ada5defe4", "type": "concept", "title": "Boundaries"}, {"id": "046ce121-49d3-4576-92e9-d160db0e5292", "type": "concept", "title": "Triangles"}, {"id": "d7277744-33e2-476d-893f-06e18c656f61", "type": "concept", "title": "Family life cycle"}], "description": "Family systems theory explains behavior through roles, rules, patterns, boundaries, and relational meanings."}, {"id": "e8c1ef59-b7b0-4f73-b2a4-8dbd2018096a", "type": "subtopic", "title": "Diversity in family forms", "children": [{"id": "32cd43a9-5ca0-4d71-933b-894891127c85", "type": "concept", "title": "Single-parent families"}, {"id": "7042b3c1-f7c2-468b-ba09-e2a425104213", "type": "concept", "title": "Blended families"}, {"id": "da8d5907-97ac-4b26-babf-c2426d9e7fa4", "type": "concept", "title": "Chosen families"}, {"id": "f9eb480c-9f00-4cc4-a1c1-44c343d42a40", "type": "concept", "title": "Multigenerational and kinship networks"}], "description": "Students examine families without treating one structure as the universal norm."}, {"id": "983d152c-c6e6-4353-ab4c-00f5f32680a8", "type": "subtopic", "title": "Family stress and support", "children": [{"id": "2cbdba3c-144f-4f71-8aca-386584ececda", "type": "concept", "title": "Caregiving strain"}, {"id": "e85be27f-537c-4868-b092-c658f1d27dfd", "type": "concept", "title": "Economic stress"}, {"id": "93635a37-96f7-4fe9-b91c-4b174601dd3b", "type": "concept", "title": "Social support"}, {"id": "90e60430-c4e5-4312-b78d-2321ad3f35bc", "type": "concept", "title": "Resilience and family strengths"}], "description": "Family functioning depends on resources, cultural meaning, stress, and access to support."}]}, {"id": "486b8cee-b9ea-42b6-b553-cf910dd9c786", "type": "topic", "title": "Group Dynamics, Mutual Aid, and Collective Change", "description": "Understand how groups shape identity, support, power, conflict, decision-making, and social work intervention.", "children": [{"id": "6cee39e5-9578-4de8-b82a-acd17c251500", "type": "subtopic", "title": "Group development and process", "children": [{"id": "c829826f-5869-4c93-b8fd-1b57b9d7985d", "type": "concept", "title": "Forming, storming, norming, performing"}, {"id": "22da00a5-7117-418e-ad87-c43cb65535f2", "type": "concept", "title": "Roles and norms"}, {"id": "03422fef-4aaf-4b05-8f93-1e3ef4faae47", "type": "concept", "title": "Cohesion"}, {"id": "8d0768ba-7c25-4d33-b969-a13e85dfd06c", "type": "concept", "title": "Conflict and repair"}], "description": "Groups have developmental patterns that affect trust, participation, conflict, and productivity."}, {"id": "0a2ed224-53d7-4406-8521-5607ef2f2bfa", "type": "subtopic", "title": "Mutual aid and therapeutic group principles", "children": [{"id": "fd94ae5e-be64-498e-8377-d099e08c181e", "type": "concept", "title": "Universality"}, {"id": "fbc7b700-acf6-453a-ab86-9000b89941e7", "type": "concept", "title": "Mutual support"}, {"id": "a31b8a62-67b9-49fa-9ff7-b123014dc6ca", "type": "concept", "title": "Peer learning"}, {"id": "a832202e-43fe-4483-932a-80d518ecadb0", "type": "concept", "title": "Facilitation stance"}], "description": "Groups can create change through shared experience, reciprocity, skill practice, and belonging."}, {"id": "b3560598-22e3-48f8-95f4-46934e6a7f21", "type": "subtopic", "title": "Task groups and collective action", "children": [{"id": "03cf2c4b-d709-4910-a192-a0158ad98888", "type": "concept", "title": "Committees and teams"}, {"id": "6f5231f3-ab99-4e06-8ce5-209f6cbcfe02", "type": "concept", "title": "Coalitions"}, {"id": "b8c19a7e-a73a-4368-b3a2-c02ac936173c", "type": "concept", "title": "Leadership distribution"}, {"id": "e7213c35-4a52-49e1-b1ad-796192907dc6", "type": "concept", "title": "Decision rules and accountability"}], "description": "Groups are also engines for planning, advocacy, governance, and community change."}]}, {"id": "f064b20e-c1bd-414a-bb31-0f110ff4d8aa", "type": "topic", "title": "Organizations as Human Service Environments", "description": "Study how organizations structure behavior, ethics, worker experience, service access, and client outcomes.", "children": [{"id": "f689da7d-2d03-40e9-b532-67109264a542", "type": "subtopic", "title": "Organizational behavior and culture", "children": [{"id": "f7a5a211-5801-4728-b3ab-f14acae14dae", "type": "concept", "title": "Formal and informal culture"}, {"id": "c9177df8-bf16-43e3-929d-e92da16c6ca2", "type": "concept", "title": "Mission and values"}, {"id": "aad0c513-e98d-4f41-9234-5e643d730199", "type": "concept", "title": "Incentives and constraints"}, {"id": "4872ff3d-7c43-4a10-843a-07e597039c45", "type": "concept", "title": "Street-level bureaucracy"}], "description": "Organizations shape what workers do, what clients receive, and what ethical choices feel possible."}, {"id": "e49e70b2-f997-419e-8427-90578675afb0", "type": "subtopic", "title": "Human service organizations", "children": [{"id": "99a561f9-4912-4910-8d5a-17bc09da6720", "type": "concept", "title": "Intake and referral"}, {"id": "01488191-e8d6-4297-9fab-818546997b9d", "type": "concept", "title": "Caseloads and workflow"}, {"id": "0175539f-da22-463a-bbe7-d3fcf5bff297", "type": "concept", "title": "Supervision and documentation"}, {"id": "4a706528-239d-4860-94e8-a87dcdfa4f94", "type": "concept", "title": "Interagency coordination"}], "description": "Students learn how social service organizations organize access, eligibility, service quality, and risk."}, {"id": "5088825e-eca9-4e19-9cbd-c5376c65a6f4", "type": "subtopic", "title": "Organizational trauma and worker sustainability", "children": [{"id": "d7d4aaef-63e0-4355-b03b-3ce98c334409", "type": "concept", "title": "Burnout and moral distress"}, {"id": "6a3db923-746c-499d-a7e7-567428b981e6", "type": "concept", "title": "Secondary traumatic stress"}, {"id": "1fd9ab43-d580-4014-8721-9d8761ae5cab", "type": "concept", "title": "Psychological safety"}, {"id": "81e40c37-addf-4540-ad0e-5ba70a46cccb", "type": "concept", "title": "Reflective supervision"}], "description": "Organizational environments can support or harm workers and clients."}]}, {"id": "2dda78ac-2415-49b2-9da4-8badaeca53b4", "type": "topic", "title": "Communities as Social Systems", "description": "Analyze neighborhoods, networks, social capital, institutions, place, and community power as environments that shape well-being.", "children": [{"id": "c37ace22-fdc0-4c29-95a2-add37cdbe5c4", "type": "subtopic", "title": "Community concepts and boundaries", "children": [{"id": "57c64210-eb64-48c4-9435-eadcbc241ad2", "type": "concept", "title": "Place-based communities"}, {"id": "54f9c8ba-b03d-466f-ba94-7ea927497bfe", "type": "concept", "title": "Identity communities"}, {"id": "14b81921-eba9-4871-aa14-d77ae3349655", "type": "concept", "title": "Communities of interest"}, {"id": "51447b88-2e40-4779-8345-8e9fa0e37ce9", "type": "concept", "title": "Digital communities"}], "description": "Communities are built through geography, identity, affiliation, shared history, and networks."}, {"id": "7ee8a1cc-bfdb-440d-9282-47c8927912f8", "type": "subtopic", "title": "Social capital and collective efficacy", "children": [{"id": "565a03b8-b082-40e5-b1b8-408da41fda66", "type": "concept", "title": "Bonding and bridging capital"}, {"id": "4b159ed2-0a2f-407c-9b42-77a3c7b8d47f", "type": "concept", "title": "Informal support"}, {"id": "bb97e106-7c39-4460-a766-f1f0acfb3f3f", "type": "concept", "title": "Collective efficacy"}, {"id": "56e035a4-07d9-4586-b65c-be6ac620939c", "type": "concept", "title": "Community leadership"}], "description": "Community well-being depends partly on trust, networks, shared norms, and capacity for collective action."}, {"id": "9b66b072-3d90-49f6-83fd-379b960ccdb7", "type": "subtopic", "title": "Place, resources, and exclusion", "children": [{"id": "69b0a031-0caa-4cc5-8cbc-90d3d5c03394", "type": "concept", "title": "Neighborhood effects"}, {"id": "5fa93a61-19a5-4595-bf17-b5345fe7a404", "type": "concept", "title": "Environmental justice"}, {"id": "db13461c-f587-4f3d-9e2a-f6b3739724dc", "type": "concept", "title": "Service deserts"}, {"id": "b19dd27d-fbe4-4eba-8ac8-05014a04068e", "type": "concept", "title": "Segregation and displacement"}], "description": "Place affects access to safety, opportunity, services, transportation, schools, food, and health."}]}, {"id": "1726b207-1113-4907-b5db-2443d6aee203", "type": "topic", "title": "Social Structures, Institutions, and Life Chances", "description": "Examine how social institutions distribute resources, risk, recognition, punishment, care, and opportunity.", "children": [{"id": "d537328f-45e4-4743-be90-0547539568bf", "type": "subtopic", "title": "Institutional analysis", "children": [{"id": "ba6b7e96-ed31-432c-8d74-d44a12a87ba1", "type": "concept", "title": "Education"}, {"id": "314b4b2e-712e-4694-845e-b527caf5df40", "type": "concept", "title": "Health care"}, {"id": "e6797674-bc42-4b93-ad5d-09167bdf9146", "type": "concept", "title": "Criminal legal system"}, {"id": "b88a32e8-3e89-4efd-af01-9db38e2d2bc3", "type": "concept", "title": "Labor and welfare systems"}], "description": "Institutions shape behavior by setting rules, norms, resources, and sanctions."}, {"id": "3f632714-e9bc-427a-9d07-b57779d0aea8", "type": "subtopic", "title": "Life chances and cumulative advantage", "children": [{"id": "52271be7-1818-4c23-a728-b99d1d75926b", "type": "concept", "title": "Cumulative inequality"}, {"id": "c3ca659f-8714-4e37-8528-6e64bf39ff68", "type": "concept", "title": "Intergenerational mobility"}, {"id": "ecf79e7a-d25d-4719-9a9f-b423048c7cae", "type": "concept", "title": "Credentialing and exclusion"}, {"id": "9e612063-3947-47f5-927b-f027fc3e065a", "type": "concept", "title": "Policy-mediated opportunity"}], "description": "Students connect structural position to cumulative opportunity and cumulative harm."}, {"id": "c2c58c48-5316-4a24-9be2-76a2696c5f12", "type": "subtopic", "title": "Institutional trust and harm", "children": [{"id": "00e69056-4af3-4bd7-825a-2d47e816524c", "type": "concept", "title": "Medical mistrust"}, {"id": "76313bed-f41f-48e5-93b2-4565ac60165c", "type": "concept", "title": "School discipline"}, {"id": "9f4f5230-54e6-417e-bf53-a689a6479435", "type": "concept", "title": "Child welfare surveillance"}, {"id": "6f8f9abb-d620-43f8-a907-e33de4ab7f6f", "type": "concept", "title": "Community-police relationships"}], "description": "People's relationships to institutions reflect both help and histories of surveillance, exclusion, and violence."}]}, {"id": "7a7777c3-30c5-473a-9f31-33593f94aa32", "type": "topic", "title": "Power, Privilege, Oppression, and Anti-Oppressive Practice", "description": "Identify how power operates across interpersonal, organizational, community, and policy systems.", "children": [{"id": "4a4b09f5-96eb-4e67-99a6-ed75bf69b93e", "type": "subtopic", "title": "Power across systems", "children": [{"id": "a3042454-374b-44dc-93f3-ed1cc3d569ac", "type": "concept", "title": "Coercive and persuasive power"}, {"id": "655ac127-35c4-4466-8e89-63676da0196f", "type": "concept", "title": "Professional power"}, {"id": "302fa592-6d54-4709-840f-3d2861f2da5f", "type": "concept", "title": "Institutional power"}, {"id": "ee2e4656-ad62-4b53-9cb4-5a2be96993cd", "type": "concept", "title": "Community power"}], "description": "Power appears in relationships, organizations, law, policy, knowledge, and professional authority."}, {"id": "43114c3a-9db5-47aa-aea9-e95715968744", "type": "subtopic", "title": "Privilege and oppression", "children": [{"id": "86659977-1b9a-4f73-a85c-149de463dcf0", "type": "concept", "title": "Racism"}, {"id": "77fbf50b-9dc2-4cf2-bf9a-d9e1bb1d1d83", "type": "concept", "title": "Sexism and heterosexism"}, {"id": "92e041ed-606e-402b-a017-4604dccdb413", "type": "concept", "title": "Ableism"}, {"id": "7efcb879-a821-4b3b-8c71-f65d3fea6726", "type": "concept", "title": "Classism and ageism"}], "description": "Students learn to see oppression as systemic, reproduced, and changeable."}, {"id": "013b3924-8e45-44a7-af3d-9aaee1cd321d", "type": "subtopic", "title": "Anti-oppressive practice", "children": [{"id": "f514a7de-4c8a-42cb-9f76-4fcfc972d47e", "type": "concept", "title": "Critical self-reflection"}, {"id": "f803470f-209c-4b80-9413-3e72e543ec5a", "type": "concept", "title": "Power sharing"}, {"id": "b6c61cc2-7eb1-4c86-829a-dc7e74a29b08", "type": "concept", "title": "Client and community voice"}, {"id": "7ae73e7e-317a-4d46-8ddf-b255f261fd29", "type": "concept", "title": "Structural intervention"}], "description": "Anti-oppressive practice links critical analysis to accountable action."}]}, {"id": "80d30447-5ead-44cb-995e-8ac86415dbab", "type": "topic", "title": "Culture, Race, Ethnicity, Migration, and Belonging", "description": "Study culture and identity as dynamic social processes shaped by history, migration, racialization, language, and belonging.", "children": [{"id": "2f060431-371f-4af9-9994-3feb9577ea0a", "type": "subtopic", "title": "Culture as dynamic context", "children": [{"id": "e19d3519-29ef-44e0-a75e-617e57bb5842", "type": "concept", "title": "Cultural humility"}, {"id": "92d69402-9e27-4df8-a231-0b582f97a65d", "type": "concept", "title": "Language and communication"}, {"id": "adbb7c41-f5f3-423a-be2f-bd8aeec4f860", "type": "concept", "title": "Religion and spirituality"}, {"id": "c6d6ecf2-9f1b-4799-9b15-5b90340f086d", "type": "concept", "title": "Cultural adaptation"}], "description": "Culture shapes meaning, identity, family life, help-seeking, and interpretation of behavior."}, {"id": "0996a733-40ed-4d82-b193-eec532947663", "type": "subtopic", "title": "Race, ethnicity, and racialization", "children": [{"id": "cd5c7cec-5525-49bf-92ac-417cc522752c", "type": "concept", "title": "Racial identity"}, {"id": "70d48863-d1f3-443c-8945-b609ee4be1ae", "type": "concept", "title": "Ethnic identity"}, {"id": "0f623ba9-fba1-49ee-80be-cec5ac30ebe8", "type": "concept", "title": "Racialization"}, {"id": "b7f3a068-6bed-484b-884a-825aa2b0e9b5", "type": "concept", "title": "Colorism and intra-group diversity"}], "description": "Race and ethnicity are lived through identity, community, institutions, and histories of power."}, {"id": "d597ffab-199c-4681-a27d-73191c39da51", "type": "subtopic", "title": "Migration and belonging", "children": [{"id": "3c9ebfc8-1026-4d10-994b-fdf615d62816", "type": "concept", "title": "Immigration status"}, {"id": "c6aa1451-e641-4435-b0db-613ec6bd1e10", "type": "concept", "title": "Refugee experience"}, {"id": "f5c1ef3b-35e0-4bd6-9f64-7e23d4b65ba6", "type": "concept", "title": "Transnational family ties"}, {"id": "938b949c-cc83-47c9-8ecf-745e072ca65b", "type": "concept", "title": "Acculturation and belonging"}], "description": "Migration changes family systems, community ties, legal vulnerability, and identity formation."}]}, {"id": "98c74c70-f698-42b6-929b-69197cca4715", "type": "topic", "title": "Social and Economic Inequality", "description": "Connect poverty, wealth, labor, housing, education, health, and policy to human behavior and social functioning.", "children": [{"id": "ece00537-0021-4a0d-af02-66caaf620d53", "type": "subtopic", "title": "Poverty and economic insecurity", "children": [{"id": "094b25f9-60aa-48b9-b967-a65e3dd90f00", "type": "concept", "title": "Income and wealth gaps"}, {"id": "e38a2457-f8c8-4e0a-816e-adc6c662ef1f", "type": "concept", "title": "Benefits cliffs"}, {"id": "7aec3234-bd24-4244-94af-7d1fee23137c", "type": "concept", "title": "Food and housing insecurity"}, {"id": "d4e9788a-5620-4be0-afb0-7c388e525246", "type": "concept", "title": "Debt and financial precarity"}], "description": "Economic inequality shapes behavior through stress, constrained choice, stigma, and material hardship."}, {"id": "88a9cf09-6f2c-4f1a-bb97-f2b33cd6a400", "type": "subtopic", "title": "Housing, education, health, and labor", "children": [{"id": "cc1238d4-3145-4014-b9c3-939e60455f79", "type": "concept", "title": "Housing markets"}, {"id": "e98b333c-cc7f-479d-b8aa-19c4dc134f42", "type": "concept", "title": "School funding and discipline"}, {"id": "3b699c11-d214-48f3-824e-b468929af1e0", "type": "concept", "title": "Health inequities"}, {"id": "b4136267-2604-400b-9cf8-b8bd957726e0", "type": "concept", "title": "Labor market segmentation"}], "description": "Major social institutions distribute resources and risks in deeply unequal ways."}, {"id": "b7f342a7-fc11-49be-b94a-31f128bac95c", "type": "subtopic", "title": "Policy and inequality", "children": [{"id": "db2c44e8-68a2-4dd2-8ea1-12aaae48ac00", "type": "concept", "title"