 map"}, {"id": "3b7d09a6-b593-42e1-a856-6b2685eb6bd1", "type": "concept", "title": "Community and policy map"}], "description": "Students apply the course by mapping a person, family, group, organization, community, and policy environment together."}, {"id": "de010009-0ef5-40dd-baf7-d7bbd3cd2a20", "type": "subtopic", "title": "Integrated formulation", "children": [{"id": "fe13d35b-3fda-4dbf-b9ac-cd18b13f51f4", "type": "concept", "title": "Risk and protective factors"}, {"id": "c7d199ca-74fb-4065-ad48-c255ae906401", "type": "concept", "title": "Power and oppression analysis"}, {"id": "ad2f9d34-f01b-4cb2-93d9-e3b1c69cade3", "type": "concept", "title": "Cultural and relational meaning"}, {"id": "0230def9-b344-437b-98c4-8df735b58538", "type": "concept", "title": "Systems hypotheses"}], "description": "The formulation links behavior to social environments without losing individual agency or structural context."}, {"id": "0c9c7e2f-df0b-42df-808b-d7bec301cc60", "type": "subtopic", "title": "Change strategy and reflection", "children": [{"id": "b9ed759e-6415-4358-81a3-55dd0cf9bf40", "type": "concept", "title": "Micro-mezzo-macro intervention plan"}, {"id": "ff0a4290-3fc5-4500-9813-88083b21543a", "type": "concept", "title": "Stakeholder engagement"}, {"id": "b96d0297-e3aa-4433-99d8-a3a9a02140da", "type": "concept", "title": "Ethical tensions"}, {"id": "4357751a-b601-448e-87a2-442faeeb7849", "type": "concept", "title": "Professional use of self"}], "description": "The final step translates analysis into ethical, feasible action at multiple levels."}]}], "dbBacked": true}$hb2json$::jsonb,
